from datetime import datetime
from typing import Any, Dict, List, Tuple


def run(rows: List[Dict[str, Any]], reference: Dict[str, List[Dict[str, Any]]]) -> Dict[str, Any]:
    # Validate input columns
    required_columns = ["Invoice No", "Vendor", "Invoice Date", "Due Date", "Amount", "Status"]
    for i, row in enumerate(rows):
        for col in required_columns:
            if col not in row:
                raise ValueError(f"Missing column '{col}' in row {i}")

    # Work on a copy
    rows = [dict(row) for row in rows]

    # Helper functions
    def blank(v: Any) -> bool:
        return v is None or (isinstance(v, str) and v.strip() == "")

    def text(v: Any) -> str:
        if v is None:
            return ""
        if isinstance(v, float) and v.is_integer():
            return str(int(v))
        return str(v)

    def normalize(v: Any, steps: List[str]) -> str:
        s = text(v)
        for step in steps:
            if step == "strip":
                s = s.strip()
            elif step == "upper":
                s = s.upper()
            elif step == "lower":
                s = s.lower()
            elif step == "collapse_spaces":
                s = " ".join(s.split())
            elif step == "digits_only":
                s = "".join(ch for ch in s if ch.isdigit())
        return s

    # Step 1: clean_text on Invoice No
    for row in rows:
        val = row.get("Invoice No")
        if isinstance(val, str):
            s = val.strip()
            if s == "":
                row["Invoice No"] = None
            else:
                row["Invoice No"] = s

    # Step 2: dedupe on Invoice No
    keys = []
    for row in rows:
        key_parts = [normalize(row.get("Invoice No"), ["strip"])]
        keys.append(tuple(key_parts))

    seen: Dict[Tuple[str, ...], int] = {}
    keep_indices = []
    for idx, key in enumerate(keys):
        if all(part == "" for part in key):
            keep_indices.append(idx)
            continue
        if key not in seen:
            seen[key] = idx
            keep_indices.append(idx)

    rows = [rows[i] for i in keep_indices]

    # Step 3: fill_blank on Status
    for row in rows:
        if blank(row.get("Status")):
            row["Status"] = "Pending"

    # Step 4: format_date on Due Date
    for row in rows:
        val = row.get("Due Date")
        if isinstance(val, str) and not blank(val):
            parsed = None
            for fmt in ["%Y-%m-%d"]:
                try:
                    parsed = datetime.strptime(val.strip(), fmt)
                    break
                except ValueError:
                    continue
            if parsed is not None:
                row["Due Date"] = parsed.strftime("%Y-%m-%d")

    # Step 5: flag Overdue
    for row in rows:
        if "Overdue" not in row:
            row["Overdue"] = None

    def evaluate_condition(row: Dict[str, Any], cond: Dict[str, Any]) -> bool:
        col = cond["column"]
        op = cond["op"]
        value = cond.get("value")
        row_val = row.get(col)

        if op == "blank":
            return blank(row_val)
        if op == "not_blank":
            return not blank(row_val)

        if op == "eq":
            if isinstance(row_val, (int, float)) and isinstance(value, (int, float)):
                return row_val == value
            return text(row_val).strip().casefold() == text(value).strip().casefold()
        if op == "ne":
            if isinstance(row_val, (int, float)) and isinstance(value, (int, float)):
                return row_val != value
            return text(row_val).strip().casefold() != text(value).strip().casefold()
        if op == "in":
            if isinstance(row_val, (int, float)):
                return any(row_val == v for v in value if isinstance(v, (int, float)))
            row_text = text(row_val).strip().casefold()
            return any(row_text == text(v).strip().casefold() for v in value)
        if op in ("gt", "gte", "lt", "lte"):
            if isinstance(row_val, (int, float)) and isinstance(value, (int, float)):
                if op == "gt":
                    return row_val > value
                if op == "gte":
                    return row_val >= value
                if op == "lt":
                    return row_val < value
                if op == "lte":
                    return row_val <= value
            if isinstance(row_val, str) and isinstance(value, str) and not blank(row_val) and not blank(value):
                rv = row_val.strip()
                vv = value.strip()
                if op == "gt":
                    return rv > vv
                if op == "gte":
                    return rv >= vv
                if op == "lt":
                    return rv < vv
                if op == "lte":
                    return rv <= vv
            return False
        if op == "contains":
            cond_text = text(value).strip().casefold()
            row_text = text(row_val).casefold()
            return cond_text in row_text
        if op == "starts_with":
            cond_text = text(value).strip().casefold()
            row_text = text(row_val).strip().casefold()
            return row_text.startswith(cond_text)
        return False

    conditions = [
        {"column": "Status", "op": "ne", "value": "Paid"},
        {"column": "Due Date", "op": "lt", "value": "2026-10-15"},
    ]
    for row in rows:
        match_all = True
        for cond in conditions:
            if not evaluate_condition(row, cond):
                match_all = False
                break
        row["Overdue"] = "Yes" if match_all else "No"

    # Step 6: sort by Due Date ascending
    sort_keys = [{"column": "Due Date", "descending": False}]
    for key_spec in reversed(sort_keys):
        col = key_spec["column"]
        descending = key_spec["descending"]
        non_blank_rows = []
        blank_rows = []
        for row in rows:
            if blank(row.get(col)):
                blank_rows.append(row)
            else:
                non_blank_rows.append(row)

        def sort_key(row: Dict[str, Any]) -> Tuple[int, Any, str]:
            v = row.get(col)
            if isinstance(v, (int, float)):
                return (0, v, "")
            return (1, 0, text(v).strip().casefold())

        non_blank_rows.sort(key=sort_key, reverse=descending)
        rows = non_blank_rows + blank_rows

    # Prepare output rows with exact column order
    output_columns = ["Invoice No", "Vendor", "Invoice Date", "Due Date", "Amount", "Status", "Overdue"]
    output_rows = []
    for row in rows:
        out_row = {col: row.get(col) for col in output_columns}
        output_rows.append(out_row)

    return {"rows": output_rows, "sheets": {}}
